#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

//! Oracle-checked tests of `CORRELATE`, `LOWERHULL`, `UPPERHULL`, `LOCATIONOFFSET` and `MOTIONSPLIT`.
//! The expectations are the answers of Warp 10 3.5.0 to the same scripts:
//! the JSON stack (top first) or the error message (in its JDK 11+ form).

use crate::tests::test_stack;
use crate::value::Value;

const A: &str = r"NEWGTS 'a' RENAME  10 NaN NaN NaN 1.284 ADDVALUE 20 NaN NaN NaN 2.394 ADDVALUE 30 NaN NaN NaN 4.509 ADDVALUE 40 NaN NaN NaN 4.005 ADDVALUE 50 NaN NaN NaN 5.049 ADDVALUE 60 NaN NaN NaN 4.278 ADDVALUE 70 NaN NaN NaN 2.731 ADDVALUE 80 NaN NaN NaN 2.301 ADDVALUE 90 NaN NaN NaN -0.219 ADDVALUE 100 NaN NaN NaN -1.086 ADDVALUE 110 NaN NaN NaN -3.367 ADDVALUE 120 NaN NaN NaN -4.603 ADDVALUE 130 NaN NaN NaN -4.796 ADDVALUE 140 NaN NaN NaN -4.341 ADDVALUE 150 NaN NaN NaN -5.547 ADDVALUE 160 NaN NaN NaN -4.62 ADDVALUE 170 NaN NaN NaN -2.636 ADDVALUE 180 NaN NaN NaN -0.502 ADDVALUE 190 NaN NaN NaN 0.405 ADDVALUE 200 NaN NaN NaN 1.664 ADDVALUE [ SWAP bucketizer.last 200 10 0 ] BUCKETIZE 0 GET";
const B: &str = r"NEWGTS 'b' RENAME { 'k' 'v' } RELABEL 10 NaN NaN NaN 4.389 ADDVALUE 20 NaN NaN NaN 3.01 ADDVALUE 30 NaN NaN NaN 4.684 ADDVALUE 40 NaN NaN NaN 3.159 ADDVALUE 50 NaN NaN NaN 2.087 ADDVALUE 60 NaN NaN NaN 0.945 ADDVALUE 70 NaN NaN NaN 0.049 ADDVALUE 80 NaN NaN NaN -0.26 ADDVALUE 90 NaN NaN NaN -2.758 ADDVALUE 100 NaN NaN NaN -2.949 ADDVALUE 110 NaN NaN NaN -3.485 ADDVALUE 120 NaN NaN NaN -4.255 ADDVALUE 130 NaN NaN NaN -3.7 ADDVALUE 140 NaN NaN NaN -4.048 ADDVALUE 150 NaN NaN NaN -3.084 ADDVALUE 160 NaN NaN NaN -1.577 ADDVALUE 170 NaN NaN NaN 0.694 ADDVALUE 180 NaN NaN NaN 1.475 ADDVALUE 190 NaN NaN NaN 2.355 ADDVALUE 200 NaN NaN NaN 3.705 ADDVALUE [ SWAP bucketizer.last 200 10 0 ] BUCKETIZE 0 GET";
const L: &str = r"NEWGTS 'l' RENAME  10 NaN NaN NaN -4 ADDVALUE 20 NaN NaN NaN -20 ADDVALUE 30 NaN NaN NaN 29 ADDVALUE 40 NaN NaN NaN 19 ADDVALUE 50 NaN NaN NaN -25 ADDVALUE 60 NaN NaN NaN 7 ADDVALUE 70 NaN NaN NaN 2 ADDVALUE 80 NaN NaN NaN 37 ADDVALUE 90 NaN NaN NaN 22 ADDVALUE 100 NaN NaN NaN -21 ADDVALUE 110 NaN NaN NaN 48 ADDVALUE 120 NaN NaN NaN -38 ADDVALUE 130 NaN NaN NaN -8 ADDVALUE 140 NaN NaN NaN 25 ADDVALUE [ SWAP bucketizer.last 140 10 0 ] BUCKETIZE 0 GET";
const C: &str = r"NEWGTS 'c' RENAME  20 NaN NaN NaN 1 ADDVALUE 40 NaN NaN NaN 2 ADDVALUE 60 NaN NaN NaN 3 ADDVALUE 80 NaN NaN NaN 4 ADDVALUE 100 NaN NaN NaN 5 ADDVALUE 120 NaN NaN NaN 6 ADDVALUE 140 NaN NaN NaN 7 ADDVALUE 160 NaN NaN NaN 8 ADDVALUE 180 NaN NaN NaN 9 ADDVALUE 200 NaN NaN NaN 10 ADDVALUE [ SWAP bucketizer.last 200 20 0 ] BUCKETIZE 0 GET";
const G: &str = r"NEWGTS 'g' RENAME  10 NaN NaN NaN 1 ADDVALUE 20 NaN NaN NaN 2 ADDVALUE 30 NaN NaN NaN 3 ADDVALUE 40 NaN NaN NaN 4 ADDVALUE 50 NaN NaN NaN 5 ADDVALUE [ SWAP bucketizer.last 50 10 0 ] BUCKETIZE 0 GET 0 NaN NaN NaN 1 ADDVALUE";
const H: &str = r"NEWGTS 'h' RENAME  5 NaN NaN NaN 3 ADDVALUE 1 NaN NaN NaN 1 ADDVALUE 2 NaN NaN NaN 4 ADDVALUE 3 NaN NaN NaN -2 ADDVALUE 4 NaN NaN NaN 5 ADDVALUE 6 NaN NaN NaN 0 ADDVALUE 7 NaN NaN NaN 7 ADDVALUE 8 NaN NaN NaN 1 ADDVALUE 9 NaN NaN NaN 1 ADDVALUE 10 NaN NaN NaN 2 ADDVALUE";
const HD: &str = r"NEWGTS 'hd' RENAME  1 NaN NaN NaN 1.5 ADDVALUE 2 NaN NaN NaN 1.5 ADDVALUE 3 NaN NaN NaN 1.5 ADDVALUE 4 NaN NaN NaN 0.5 ADDVALUE";
const S: &str = r"NEWGTS 's' RENAME 1 NaN NaN NaN 'x' ADDVALUE 2 NaN NaN NaN 'y' ADDVALUE";
const P: &str = r"NEWGTS 'p' RENAME 1 48.0 2.0 0 1 ADDVALUE 2 48.0001 2.0 0 2 ADDVALUE 3 48.01 2.0 NaN 3 ADDVALUE 4 NaN NaN NaN 4 ADDVALUE 5 48.0105 2.0 0 5 ADDVALUE 6 48.5 2.5 3 6 ADDVALUE 7 48.5001 2.5 3 7 ADDVALUE";
const NOLOC: &str = r"NEWGTS 'n' RENAME  1 NaN NaN NaN 1 ADDVALUE 2 NaN NaN NaN 2 ADDVALUE 3 NaN NaN NaN 3 ADDVALUE";
const BS: &str = r"NEWGTS 'bs' RENAME 10 NaN NaN NaN 'x' ADDVALUE 20 NaN NaN NaN 'y' ADDVALUE [ SWAP bucketizer.last 20 10 0 ] BUCKETIZE 0 GET";
const TRIP: &str = r"NEWGTS 'trip' RENAME 60000000 48.002 2.0 NaN 0 ADDVALUE 120000000 48.004 2.0 NaN 1 ADDVALUE 180000000 48.006 2.0 NaN 2 ADDVALUE 240000000 48.008 2.0 NaN 3 ADDVALUE 300000000 48.01 2.0 NaN 4 ADDVALUE 360000000 48.012 2.0 NaN 5 ADDVALUE 420000000 48.014 2.0 NaN 6 ADDVALUE 480000000 48.016 2.0 NaN 7 ADDVALUE 540000000 48.018 2.0 NaN 8 ADDVALUE 600000000 48.02 2.0 NaN 9 ADDVALUE 660000000 48.02 2.0 NaN 100 ADDVALUE 720000000 48.02001 2.0 NaN 101 ADDVALUE 780000000 48.02 2.0 NaN 102 ADDVALUE 840000000 48.02001 2.0 NaN 103 ADDVALUE 900000000 48.02 2.0 NaN 104 ADDVALUE 960000000 48.02001 2.0 NaN 105 ADDVALUE 1020000000 48.02 2.0 NaN 106 ADDVALUE 1080000000 48.02001 2.0 NaN 107 ADDVALUE 1140000000 48.02 2.0 NaN 108 ADDVALUE 1200000000 48.02001 2.0 NaN 109 ADDVALUE 1260000000 48.02 2.003 NaN 200 ADDVALUE 1320000000 48.02 2.006 NaN 201 ADDVALUE 1380000000 48.02 2.009 NaN 202 ADDVALUE 1440000000 48.02 2.012 NaN 203 ADDVALUE 1500000000 48.02 2.015 NaN 204 ADDVALUE 5100000000 48.02 2.015 NaN 300 ADDVALUE 5160000000 50.0 3.0 NaN 301 ADDVALUE 5220000000 NaN NaN NaN 302 ADDVALUE 5280000000 50.0 3.0 NaN 400 ADDVALUE 5340000000 50.0 3.000001 NaN 401 ADDVALUE 5400000000 50.0 3.000002 NaN 402 ADDVALUE 5460000000 50.0 3.000003 NaN 403 ADDVALUE 5520000000 50.0 3.000004 NaN 404 ADDVALUE 5580000000 50.0 3.000005 NaN 405 ADDVALUE";

/// The script of a template, its `@NAME` placeholders replaced by the series above.
fn expand(template: &str) -> String {
    template
        .replace("@NOLOC", NOLOC)
        .replace("@TRIP", TRIP)
        .replace("@HD", HD)
        .replace("@BS", BS)
        .replace("@A", A)
        .replace("@B", B)
        .replace("@L", L)
        .replace("@C", C)
        .replace("@G", G)
        .replace("@H", H)
        .replace("@S", S)
        .replace("@P", P)
}

/// The stack left by `script`, top first, as the JSON array of the Warp 10 exec endpoint,
/// or the error message.
fn stack_json(script: &str) -> Result<String, String> {
    let mut stack = test_stack();
    stack
        .exec_checked(&format!("{script} DEPTH ->LIST REVERSE ->JSON"))
        .map_err(|err| err.to_string())?;
    match stack.pop().unwrap() {
        Value::String(json) => Ok(json.to_string()),
        other => panic!("not a string: {other:?}"),
    }
}

/// Check every case, reporting all the mismatches at once.
fn check(cases: &[(&str, Result<&str, &str>)]) {
    let mut failures = Vec::new();
    for (template, expected) in cases {
        let script = expand(template);
        match (expected, stack_json(&script)) {
            (Ok(json), Ok(actual)) if actual == *json => {}
            (Err(message), Err(actual)) if actual.contains(message) => {}
            (expected, actual) => failures.push(format!(
                "{template}\n  expected {expected:?}\n  actual   {actual:?}"
            )),
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn correlate() {
    check(&[
        (
            r"@A [ @B ] [ 0 10 20 -10 100 ] CORRELATE",
            Ok(
                r#"[[{"c":"b","l":{"k":"v"},"a":{},"la":0,"v":[[0,0.78296425232592],[10,0.5502179115932507],[20,0.26591643996632036],[-10,0.9229655457559676],[100,-0.7096729937021755]]}]]"#,
            ),
        ),
        (
            r"@A @B [ 0 50 ] CORRELATE",
            Ok(
                r#"[[{"c":"b","l":{"k":"v"},"a":{},"la":0,"v":[[0,0.78296425232592],[50,-0.6473019698705951]]}]]"#,
            ),
        ),
        (
            r"@A [ @A @B ] [ 0 10 ] CORRELATE",
            Ok(
                r#"[[{"c":"a","l":{},"a":{},"la":0,"v":[[0,0.9999999999999998],[10,0.9201528917297607]]},{"c":"b","l":{"k":"v"},"a":{},"la":0,"v":[[0,0.78296425232592],[10,0.5502179115932507]]}]]"#,
            ),
        ),
        (
            r"@A 'a' STORE $a [ $a ] [ 0 30 ] CORRELATE",
            Ok(
                r#"[[{"c":"a","l":{},"a":{},"la":0,"v":[[0,0.9999999999999998],[30,0.5548186534568863]]}]]"#,
            ),
        ),
        (
            r"@A [ @L ] [ 0 ] CORRELATE",
            Ok(r#"[[{"c":"l","l":{},"a":{},"la":0,"v":[[0,0.05495139773432461]]}]]"#),
        ),
        (
            r"@A [ @B ] [ ] CORRELATE",
            Ok(r#"[[{"c":"b","l":{"k":"v"},"a":{},"la":0,"v":[]}]]"#),
        ),
        (r"@A [ ] [ 0 ] CORRELATE", Ok(r"[[]]")),
        (
            r"@A [ @B ] [ 5 ] CORRELATE",
            Err(r"CORRELATE expects offsets to be multiples of the bucketspan (10)."),
        ),
        (
            r"@A [ @C ] [ 0 ] CORRELATE",
            Err(
                r"CORRELATE operates on bucketized Geo Time Series with all the same bucketspan. The expected bucketspan is 10",
            ),
        ),
        (
            r"@A [ @G ] [ 0 ] CORRELATE",
            Err(r"CORRELATE operates on bucketized, filled numeric Geo Time Series."),
        ),
        (
            r"@G [ @A ] [ 0 ] CORRELATE",
            Err(r"CORRELATE operates on bucketized, filled numeric Geo Time Series."),
        ),
        (
            r"@S [ @A ] [ 0 ] CORRELATE",
            Err(r"CORRELATE operates on bucketized, filled numeric Geo Time Series."),
        ),
        (
            r"@A [ @S ] [ 0 ] CORRELATE",
            Err(r"CORRELATE operates on bucketized, filled numeric Geo Time Series."),
        ),
        (
            r"@A [ @B ] [ 'x' ] CORRELATE",
            Err(r"class java.lang.String cannot be cast to class java.lang.Number"),
        ),
        (
            r"@A [ @B ] [ NULL ] CORRELATE",
            Err(r"NullPointerException"),
        ),
        (
            r"@A [ @B ] [ 10.7 ] CORRELATE",
            Ok(r#"[[{"c":"b","l":{"k":"v"},"a":{},"la":0,"v":[[10,0.5502179115932507]]}]]"#),
        ),
        (
            r"@A [ @B ] 0 CORRELATE",
            Err(r"CORRELATE expects a list of offsets on the top of the stack."),
        ),
        (
            r"@A [ @B 1 ] [ 0 ] CORRELATE",
            Err(r"CORRELATE can only operate on Geo Time Series instances."),
        ),
        (
            r"@A 1 [ 0 ] CORRELATE",
            Err(r"CORRELATE can only operate on Geo Time Series instances."),
        ),
        (
            r"1 [ @B ] [ 0 ] CORRELATE",
            Err(r"CORRELATE expects a Geo Time Series two levels below the top of the stack."),
        ),
        (r"[ @B ] [ 0 ] CORRELATE", Err(r"Empty stack.")),
        (
            r"@A [ @B ] [ 190 ] CORRELATE",
            Ok(r#"[[{"c":"b","l":{"k":"v"},"a":{},"la":0,"v":[[190,0.0]]}]]"#),
        ),
        (
            r"@A [ @B ] [ 200 -200 ] CORRELATE",
            Ok(r#"[[{"c":"b","l":{"k":"v"},"a":{},"la":0,"v":[[200,0.0],[-200,0.0]]}]]"#),
        ),
        (
            r"@A [ @B ] [ 180 ] CORRELATE",
            Ok(r#"[[{"c":"b","l":{"k":"v"},"a":{},"la":0,"v":[[180,0.9999999999999998]]}]]"#),
        ),
        (
            r"@H [ @B ] [ 0 ] CORRELATE",
            Err(r"CORRELATE operates on bucketized, filled numeric Geo Time Series."),
        ),
        (r"CORRELATE", Err(r"Empty stack.")),
        (r"[ 0 ] CORRELATE", Err(r"Empty stack.")),
        (
            r"@BS [ @A ] [ 0 ] CORRELATE",
            Err(r"CORRELATE operates on bucketized, filled numeric Geo Time Series."),
        ),
    ]);
}

#[test]
fn hulls() {
    check(&[
        (
            r"@H LOWERHULL",
            Ok(r#"[{"c":"h","l":{},"a":{},"la":0,"v":[[1,1],[3,-2],[9,1],[10,2]]}]"#),
        ),
        (
            r"@HD LOWERHULL",
            Ok(r#"[{"c":"hd","l":{},"a":{},"la":0,"v":[[1,1.5],[4,0.5]]}]"#),
        ),
        (
            r"@A LOWERHULL",
            Ok(
                r#"[{"c":"a","l":{},"a":{},"la":0,"v":[[10,1.284],[120,-4.603],[150,-5.547],[160,-4.62],[200,1.664]]}]"#,
            ),
        ),
        (
            r"[ @H @L ] LOWERHULL",
            Ok(
                r#"[[{"c":"h","l":{},"a":{},"la":0,"v":[[1,1],[3,-2],[9,1],[10,2]]},{"c":"l","l":{},"a":{},"la":0,"v":[[10,-4],[20,-20],[120,-38],[130,-8],[140,25]]}]]"#,
            ),
        ),
        (
            r"NEWGTS LOWERHULL",
            Ok(r#"[{"c":"","l":{},"a":{},"la":0,"v":[]}]"#),
        ),
        (r"@S LOWERHULL", Err(r"LOWERHULL expects a numeric GTS.")),
        (
            r"[ @H 1 ] LOWERHULL",
            Err(r"LOWERHULL can only operate on Geo Time Series instances."),
        ),
        (
            r"1 LOWERHULL",
            Err(r"LOWERHULL can only operate on Geo Time Series instances."),
        ),
        (
            r"NEWGTS 1 NaN NaN NaN 1 ADDVALUE 2 NaN NaN NaN 2 ADDVALUE LOWERHULL",
            Ok(r#"[{"c":"","l":{},"a":{},"la":0,"v":[[1,1],[2,2]]}]"#),
        ),
        (
            r"@H 'h' STORE $h LOWERHULL DROP $h",
            Ok(
                r#"[{"c":"h","l":{},"a":{},"la":0,"v":[[1,1],[2,4],[3,-2],[4,5],[5,3],[6,0],[7,7],[8,1],[9,1],[10,2]]}]"#,
            ),
        ),
        (r"LOWERHULL", Err(r"Empty stack.")),
        (
            r"NEWGTS 1 NaN NaN NaN 1 ADDVALUE 2 NaN NaN NaN 1 ADDVALUE 3 NaN NaN NaN 1 ADDVALUE 4 NaN NaN NaN 1 ADDVALUE LOWERHULL",
            Ok(r#"[{"c":"","l":{},"a":{},"la":0,"v":[[1,1],[2,1],[3,1],[4,1]]}]"#),
        ),
        (
            r"@H UPPERHULL",
            Ok(r#"[{"c":"h","l":{},"a":{},"la":0,"v":[[1,1],[2,4],[7,7],[10,2]]}]"#),
        ),
        (
            r"@HD UPPERHULL",
            Ok(r#"[{"c":"hd","l":{},"a":{},"la":0,"v":[[1,1.5],[2,1.5],[3,1.5],[4,0.5]]}]"#),
        ),
        (
            r"@A UPPERHULL",
            Ok(
                r#"[{"c":"a","l":{},"a":{},"la":0,"v":[[10,1.284],[30,4.509],[50,5.049],[200,1.664]]}]"#,
            ),
        ),
        (
            r"[ @H @L ] UPPERHULL",
            Ok(
                r#"[[{"c":"h","l":{},"a":{},"la":0,"v":[[1,1],[2,4],[7,7],[10,2]]},{"c":"l","l":{},"a":{},"la":0,"v":[[10,-4],[30,29],[110,48],[140,25]]}]]"#,
            ),
        ),
        (
            r"NEWGTS UPPERHULL",
            Ok(r#"[{"c":"","l":{},"a":{},"la":0,"v":[]}]"#),
        ),
        (r"@S UPPERHULL", Err(r"UPPERHULL expects a numeric GTS.")),
        (
            r"[ @H 1 ] UPPERHULL",
            Err(r"UPPERHULL can only operate on Geo Time Series instances."),
        ),
        (
            r"1 UPPERHULL",
            Err(r"UPPERHULL can only operate on Geo Time Series instances."),
        ),
        (
            r"NEWGTS 1 NaN NaN NaN 1 ADDVALUE 2 NaN NaN NaN 2 ADDVALUE UPPERHULL",
            Ok(r#"[{"c":"","l":{},"a":{},"la":0,"v":[[1,1],[2,2]]}]"#),
        ),
        (
            r"@H 'h' STORE $h UPPERHULL DROP $h",
            Ok(
                r#"[{"c":"h","l":{},"a":{},"la":0,"v":[[1,1],[2,4],[3,-2],[4,5],[5,3],[6,0],[7,7],[8,1],[9,1],[10,2]]}]"#,
            ),
        ),
        (r"UPPERHULL", Err(r"Empty stack.")),
        (
            r"NEWGTS 1 NaN NaN NaN 1 ADDVALUE 2 NaN NaN NaN 1 ADDVALUE 3 NaN NaN NaN 1 ADDVALUE 4 NaN NaN NaN 1 ADDVALUE UPPERHULL",
            Ok(r#"[{"c":"","l":{},"a":{},"la":0,"v":[[1,1],[2,1],[3,1],[4,1]]}]"#),
        ),
    ]);
}

#[test]
fn locationoffset() {
    check(&[
        (
            r"@P 100 LOCATIONOFFSET",
            Ok(
                r#"[{"c":"p","l":{},"a":{},"la":0,"v":[[1,47.99999998882413,1.9999999646097422,0,1],[3,48.00999997649342,1.9999999646097422,3],[6,48.49999995902181,2.4999999348074198,3,6],[7,48.50009999703616,2.4999999348074198,3,7]]}]"#,
            ),
        ),
        (
            r"@P 10.0 LOCATIONOFFSET",
            Ok(
                r#"[{"c":"p","l":{},"a":{},"la":0,"v":[[1,47.99999998882413,1.9999999646097422,0,1],[2,48.000099984928966,1.9999999646097422,0,2],[3,48.00999997649342,1.9999999646097422,3],[5,48.010499998927116,1.9999999646097422,0,5],[6,48.49999995902181,2.4999999348074198,3,6],[7,48.50009999703616,2.4999999348074198,3,7]]}]"#,
            ),
        ),
        (
            r"@P 1000000 LOCATIONOFFSET",
            Ok(
                r#"[{"c":"p","l":{},"a":{},"la":0,"v":[[1,47.99999998882413,1.9999999646097422,0,1],[7,48.50009999703616,2.4999999348074198,3,7]]}]"#,
            ),
        ),
        (
            r"@P 0 LOCATIONOFFSET",
            Ok(
                r#"[{"c":"p","l":{},"a":{},"la":0,"v":[[1,47.99999998882413,1.9999999646097422,0,1],[2,48.000099984928966,1.9999999646097422,0,2],[3,48.00999997649342,1.9999999646097422,3],[5,48.010499998927116,1.9999999646097422,0,5],[6,48.49999995902181,2.4999999348074198,3,6],[7,48.50009999703616,2.4999999348074198,3,7]]}]"#,
            ),
        ),
        (
            r"[ @P @NOLOC ] 50 LOCATIONOFFSET",
            Ok(
                r#"[[{"c":"p","l":{},"a":{},"la":0,"v":[[1,47.99999998882413,1.9999999646097422,0,1],[3,48.00999997649342,1.9999999646097422,3],[5,48.010499998927116,1.9999999646097422,0,5],[6,48.49999995902181,2.4999999348074198,3,6],[7,48.50009999703616,2.4999999348074198,3,7]]},{"c":"n","l":{},"a":{},"la":0,"v":[[1,1],[3,3]]}]]"#,
            ),
        ),
        (
            r"NEWGTS 10 LOCATIONOFFSET",
            Ok(r#"[{"c":"","l":{},"a":{},"la":0,"v":[]}]"#),
        ),
        (
            r"NEWGTS 1 48.0 2.0 NaN 1 ADDVALUE 10 LOCATIONOFFSET",
            Ok(
                r#"[{"c":"","l":{},"a":{},"la":0,"v":[[1,47.99999998882413,1.9999999646097422,1]]}]"#,
            ),
        ),
        (
            r"@P 'x' LOCATIONOFFSET",
            Err(r"LOCATIONOFFSET expects a distance in meters on top of the stack."),
        ),
        (
            r"1 10 LOCATIONOFFSET",
            Err(r"LOCATIONOFFSET can only operate on Geo Time Series instances."),
        ),
        (
            r"@P LOCATIONOFFSET",
            Err(r"LOCATIONOFFSET expects a distance in meters on top of the stack."),
        ),
        (r"LOCATIONOFFSET", Err(r"Empty stack.")),
        (
            r"NEWGTS 1 NaN NaN NaN 1 ADDVALUE 2 48.0 2.0 NaN 2 ADDVALUE 3 48.0 2.0 NaN 3 ADDVALUE 4 49.0 2.0 NaN 4 ADDVALUE 5 NaN NaN NaN 5 ADDVALUE 10 LOCATIONOFFSET",
            Ok(
                r#"[{"c":"","l":{},"a":{},"la":0,"v":[[1,1],[2,47.99999998882413,1.9999999646097422,2],[4,48.999999971129,1.9999999646097422,4],[5,5]]}]"#,
            ),
        ),
    ]);
}

